pins=[]
def pin(p):
    b=p.read_bytes()
    r={'path':p.as_posix(),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
    pins.append(r)
    return r
def new(p,text):
    assert p.resolve().is_relative_to(ROOT) and not p.exists()
    b=text.encode('utf-8')
    assert b
    t=p.with_name(p.name+'.tmp_'+datetime.now().strftime('%H%M%S_%f'))
    with t.open('xb') as f:
        f.write(b)
        f.flush()
        os.fsync(f.fileno())
    assert t.read_bytes()==b
    t.rename(p)
    assert p.read_bytes()==b
    return pin(p)
